original:
        bcs @sxb
        dex
@sxb:   sec

        dec SECTAB-2*SECENT+SE_T1H,x
@p2dur: lda SECTAB-SECENT+SE_T1L,x
        sec

proposal:
        dec SECTAB-2*SECENT+SE_T1H,x
        sec                        ; (C = 1 both ways into @p2dur)
@p2dur: lda SECTAB-SECENT+SE_T1L,x

original:
        cpx #OT_MUMMY-OT_MASK+1    ; OT_MASK, OT_MUMMY: X = 0, 1 (3, 4 wrap to $FE, $FF)
        bcs :+
@t256a: jmp @t256

        bgt16 spx, px, @f66
        lda #SPR_BAT0+4            ; (falling: the wide pair, facing Cleo)
        bne @fgo                   ; always: Z = 0 from the lda
@f66:   lda #SPR_BAT0+5
@fgo:   jmp add_sprite

@fr:    stx q1
        bge16 px, ox, @fr1
        inc q1                     ; (+1: facing left)
@fr1:   mov16 spy, oy

proposal:
@fr:    bge16 px, ox, @fr1         ; (X kept: the macro uses A only)
        inx                        ; (+1: facing left)
@fr1:   stx q1
        mov16 spy, oy

@stepn: lda py                     ; negative means -1 (below it was a wall): py -= 1
        bne @sdec                  ;  (A is dead: @alt0 reloads it)
        dec py+1
@sdec:  dec py
